[ExtensionOf(classStr(NumberSeqModuleJobManager))]
internal final class AVANumberSeqModuleJobManager_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
protected void loadModule()
{
    next loadModule();

    NumberSeqDatatype datatype = NumberSeqDatatype::construct();

    datatype.parmDatatypeId(extendedtypenum(AVANdxSFCId));
    datatype.parmReferenceHelp(literalstr("@NDX:NXABDENum"));
    datatype.parmWizardIsContinuous(false);
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardFetchAheadQty(10);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmWizardHighest(999999);
    datatype.parmSortField(70);
    datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(datatype);

}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>NumberSequenceReference</returns>
public static NumberSequenceReference       numRefNdxSfcId()
{
    return NumberSeqReference::findReference(extendedTypeNum(AVANdxSFCId));
}
